'use client';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useRef } from 'react';

export function VirtualGrid({ items }: { items: any[] }) {
  const parent = useRef<HTMLDivElement>(null);
  const rowCount = Math.ceil(items.length / {{cols}});
  const v = useVirtualizer({ count: rowCount, getScrollElement: () => parent.current, estimateSize: () => {{cell_size}} });
  return (
    <div ref={parent} style={{ height: 500, overflow: 'auto' }}>
      <div style={{ height: v.getTotalSize(), position: 'relative' }}>
        {v.getVirtualItems().map(r => (
          <div key={r.key} style={{ position:'absolute', top:0, transform:`translateY(${r.start}px)`, display:'grid', gridTemplateColumns:`repeat({{cols}}, 1fr)`, width:'100%' }}>
            {items.slice(r.index*{{cols}}, r.index*{{cols}}+{{cols}}).map((it,i) => <div key={i} style={{ height:{{cell_size}} }}>{it.label}</div>)}
          </div>
        ))}
      </div>
    </div>
  );
}
